def sha(b):return hashlib.sha256(b).hexdigest()
def git(r,*args):return subprocess.check_output(['git',*args],cwd=r,text=True,stderr=subprocess.PIPE).strip()
def need(c,m):
 if not c:raise RuntimeError(m)
def safe(r,name):
 p=PurePosixPath(name);need(not p.is_absolute() and '..' not in p.parts and ':' not in name and '\\' not in name and p.parts and p.parts[0]!='.git','Unsafe path '+name)
 target=r/name
 for q in [target,*target.parents]:
  if q==r.parent:break
  need(not q.is_symlink(),'Symlink escape/collision: '+name)
  if q!=target:need(not q.exists() or q.is_dir(),'File blocks destination parent: '+name)
 need(not target.exists() or target.is_file(),'Non-file destination collision: '+name)
 return target

def decode():
 b=zlib.decompress(base64.b85decode(PAYLOAD));need(sha(b)==PAYLOAD_SHA,'Payload checksum mismatch');p=json.loads(b);need(p['base']==BASE and p['repository']==REPOSITORY,'Payload identity');return p

def protect(r,p):
 for x in p['protected']:
  q=safe(r,x['path']);need(q.is_file() and sha(q.read_bytes())==x['sha256'],'Protected bytes changed: '+x['path']);need(('100755' if q.stat().st_mode&0o111 else '100644')==x['mode'],'Protected mode changed: '+x['path'])

def preflight(r,p):
 need(Path(git(r,'rev-parse','--show-toplevel')).resolve()==r,'Run at target repository root')
 url=git(r,'remote','get-url','origin').lower().rstrip('/').removesuffix('.git')
 need(url in {'https://github.com/'+REPOSITORY.lower(),'git@github.com:'+REPOSITORY.lower(),'ssh://git@github.com/'+REPOSITORY.lower()},'Wrong repository origin')
 need(git(r,'merge-base',BASE,'HEAD')==BASE,'Source commit is not an ancestor; re-audit required')
 dirty=git(r,'status','--porcelain','--untracked-files=all')
 protect(r,p)
 paths=git(r,'ls-files').splitlines();seen={unicodedata.normalize('NFC',x).casefold():x for x in paths};todo=[]
 for x in p['files']:
  q=safe(r,x['path']);data=base64.b64decode(x['content_b64'],validate=True);need(sha(data)==x['after'],'Payload row hash')
  mode=('100755' if q.stat().st_mode&0o111 else '100644') if q.is_file() else None
  actual=sha(q.read_bytes()) if q.is_file() else None
  folded=unicodedata.normalize('NFC',x['path']).casefold();need(folded not in seen or seen[folded]==x['path'],'Case-fold/Unicode collision');seen[folded]=x['path']
  if x['path'].startswith('.github/'):
   need(x['path']==MANUAL_WORKFLOW and actual==x['after'],'Upload the supplied repository-cleanup-current.yml to .github/workflows/ first; this token is not used to modify workflow files')
   continue
  if actual==x['after'] and mode==x['mode']:continue
  need(actual==x['before'] and mode==x['before_mode'],'Unexpected source/destination bytes or mode: '+x['path']);todo.append(x)
 if dirty:
  allowed={x['path'] for x in p['files']}
  observed=set(git(r,'diff','--name-only').splitlines())|set(git(r,'diff','--cached','--name-only').splitlines())|set(git(r,'ls-files','--others','--exclude-standard').splitlines())
  need(not todo and observed<=allowed,'Uncommitted/untracked changes; preserve operator work and use a clean checkout')
 return todo

def commands(r):
 records=[]
 for cmd in [[sys.executable,'tests/programs/model_campaign.py','validate'],[sys.executable,'-m','unittest','discover','-v','-s','tests/programs']]:
  x=subprocess.run(cmd,cwd=r,text=True,capture_output=True);records.append({'command':cmd,'exit_code':x.returncode,'stdout_tail':(x.stdout+x.stderr)[-9000:]});need(x.returncode==0,'Cleanup validation failed: '+str(cmd)+'\n'+records[-1]['stdout_tail'])
 return records

def apply(r,p,validate=True):
 head=git(r,'rev-parse','HEAD');todo=preflight(r,p)
 if not todo:return {'status':'ALREADY_APPLIED','base_head':head,'changed':[],'publication_performed':False}
 backups={x['path']:((r/x['path']).read_bytes(),(r/x['path']).stat().st_mode&0o777) if (r/x['path']).is_file() else None for x in todo}
 written=[];temporary=[]
 try:
  for x in todo:
   q=safe(r,x['path']);q.parent.mkdir(parents=True,exist_ok=True)
   with tempfile.NamedTemporaryFile(dir=q.parent,delete=False) as f:
    tmp=Path(f.name);temporary.append(tmp);f.write(base64.b64decode(x['content_b64']))
   tmp.chmod(0o755 if x['mode']=='100755' else 0o644);os.replace(tmp,q);written.append(x['path'])
  protect(r,p);checks=commands(r) if validate else []
  need(git(r,'rev-parse','HEAD')==head,'HEAD moved during local installation');protect(r,p)
  for x in p['files']:need(sha(safe(r,x['path']).read_bytes())==x['after'],'Installed content mismatch '+x['path'])
  return {'status':'VALIDATED_LOCAL_BATCH','base_head':head,'changed':[x['path'] for x in todo],'checks':checks,'publication_performed':False,'payload_sha256':PAYLOAD_SHA}
 except Exception:
  for tmp in temporary:
   if tmp.is_file():tmp.unlink()
  expected={x['path']:x['after'] for x in todo};conflicts=[]
  for name in reversed(written):
   old=backups[name];q=safe(r,name)
   if not q.is_file() or sha(q.read_bytes())!=expected[name]:conflicts.append(name);continue
   if old is None:q.unlink()
   else:q.write_bytes(old[0]);q.chmod(old[1])
  if conflicts:raise RuntimeError('Concurrent changes retained; manual scoped recovery required: '+str(conflicts))
  raise

def publish(r,p,result,branch):
 need(os.environ.get('GITHUB_ACTIONS')=='true' and os.environ.get('GITHUB_EVENT_NAME')=='workflow_dispatch','Publication requires manual GitHub Actions')
 need(os.environ.get('GITHUB_REPOSITORY')==REPOSITORY and os.environ.get('GITHUB_REF')=='refs/heads/'+branch,'Dispatch identity mismatch')
 event=json.loads(Path(os.environ['GITHUB_EVENT_PATH']).read_text());need(event.get('inputs',{}).get('mode')=='install','Explicit mode=install required')
 need(git(r,'rev-parse','HEAD')==result['base_head'],'HEAD changed before publication')
 actual=git(r,'ls-remote','origin','refs/heads/'+branch).split()[0];need(actual==result['base_head'],'Remote branch moved; no force or retry')
 if not result['changed']:return {**result,'status':'ALREADY_APPLIED_REMOTE_UNCHANGED'}
 need(not git(r,'diff','--cached','--name-only'),'Index contains unrelated changes')
 run=os.environ.get('GITHUB_RUN_ID','');attempt=os.environ.get('GITHUB_RUN_ATTEMPT','');need(run.isdigit() and attempt.isdigit(),'Missing actual workflow run identity')
 record=p['run_directory']+'/INSTALLATION_RECORDS/'+run+'-'+attempt+'.json';q=safe(r,record);need(not q.exists(),'Installation record collision');q.parent.mkdir(parents=True,exist_ok=True);q.write_text(json.dumps({**result,'status':'VALIDATED_CLEANUP_TRANSACTION','workflow_run':run,'workflow_attempt':attempt,'source_base':BASE,'scientific_state_changed':False},indent=2)+'\n')
 paths=result['changed']+[record];need(all(not n.startswith('.github/') for n in paths),'Workflow write is forbidden in this contents-only transaction')
 subprocess.run(['git','add','--',*paths],cwd=r,check=True)
 need(set(git(r,'diff','--cached','--name-only').splitlines())==set(paths),'Unrelated staged changes')
 for x in p['files']:
  if x['path'] in result['changed']:
   staged=subprocess.check_output(['git','show',':'+x['path']],cwd=r);need(sha(staged)==x['after'],'Git clean filter changed staged bytes')
 subprocess.run(['git','-c','user.name=github-actions[bot]','-c','user.email=41898282+github-actions[bot]@users.noreply.github.com','commit','-m','Organize current model maintenance and preserve scientific history'],cwd=r,check=True)
 commit=git(r,'rev-parse','HEAD');tree=git(r,'rev-parse','HEAD^{tree}');need(git(r,'rev-parse','HEAD^')==result['base_head'],'Commit parent mismatch')
 subprocess.run(['git','push','origin',commit+':refs/heads/'+branch],cwd=r,check=True)
 need(git(r,'ls-remote','origin','refs/heads/'+branch).split()[0]==commit,'Remote ref verification failed')
 subprocess.run(['git','fetch','origin','refs/heads/'+branch],cwd=r,check=True)
 need(git(r,'rev-parse','FETCH_HEAD')==commit and git(r,'rev-parse','FETCH_HEAD^{tree}')==tree,'Fetched remote tree differs');protect(r,p)
 return {**result,'status':'REMOTE_UPDATED','commit':commit,'tree':tree,'publication_performed':True,'remote_verified':True}

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--root',type=Path,default=Path.cwd());parser.add_argument('--mode',choices=['preview','apply','install'],default='preview');parser.add_argument('--branch',default='main');a=parser.parse_args();r=a.root.resolve();p=decode()
 if a.mode=='install':need(os.environ.get('GITHUB_ACTIONS')=='true','mode=install requires Actions; local use is --mode apply')
 try:
  if a.mode=='preview':result={'status':'PREVIEW','changed':[x['path'] for x in preflight(r,p)],'publication_performed':False}
  else:
   result=apply(r,p)
   if a.mode=='install':result=publish(r,p,result,a.branch)
  OUT.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));return 0
 except Exception as e:
  OUT.write_text(json.dumps({'status':'BLOCKED_OR_FAILED','error':str(e),'remote_success_not_claimed':True},indent=2)+'\n');print(str(e),file=sys.stderr);return 1
if __name__=='__main__':raise SystemExit(main())
